"""
PARÁMETROS COMPLETOS DEL MODELO DE OPTIMIZACIÓN
Todos los parámetros escritos en formato de listas literales
Generado automáticamente desde datos reales del 15 de septiembre de 2024
Con 5% de la demanda total y semilla específica para reproducibilidad
"""

def max_en_listas(x):
    maximo = float('-inf')  # valor inicial muy pequeño
    
    for elem in x:
        if isinstance(elem, list):
            # Si el elemento es otra lista, buscar el máximo dentro de ella recursivamente
            maximo = max(maximo, max_en_listas(elem))
        else:
            # Si es un número (u otro tipo comparable), lo comparamos directamente
            maximo = max(maximo, elem)
    
    return maximo

# PARÁMETROS PRINCIPALES
N = 67  # zonas
A = 300  # cantidad de autos
Tr = 96  # tiempo real (períodos)
Capchg = 55  # capacidad de autos en las estaciones de carga
Tchg = 8  # tiempo de carga en períodos
Cargamax = 350  # máximo de carga
maxAum = 8  # aumento máximo de tiempo
T = 104  # tiempo extendido

